dtsPropsFor.Card:
/** Card heading. Becomes the whole-card link when `href` is set. */
title: string;
/** Icon shown in an IconBox above the title. */
icon?: "mobile" | "web" | "mvp" | "booking" | "dispatch" | "records" | "facebook" | "instagram" | "tooth" | "stethoscope" | "dumbbell" | "coffee" | "utensils" | "building" | "design" | "modernize" | "consulting" | "quote" | "ownership" | "support" | "direct";
/** Makes the whole card a link (hover lift is reserved for link cards). */
href?: string;
/** Short caption under the title, in the muted meta size. */
tag?: string;
/** Body: a paragraph string, or any children (chips, lists, links). */
children?: React.ReactNode;
className?: string;

dtsPropsFor.IconBox:
/** One of the design system's own line icons. */
icon: "mobile" | "web" | "mvp" | "booking" | "dispatch" | "records" | "facebook" | "instagram" | "tooth" | "stethoscope" | "dumbbell" | "coffee" | "utensils" | "building" | "design" | "modernize" | "consulting" | "quote" | "ownership" | "support" | "direct";
className?: string;

dtsPropsFor.Icon:
/** One of the design system's own line icons (24px grid, stroke = currentColor). */
name: "mobile" | "web" | "mvp" | "booking" | "dispatch" | "records" | "facebook" | "instagram" | "tooth" | "stethoscope" | "dumbbell" | "coffee" | "utensils" | "building" | "design" | "modernize" | "consulting" | "quote" | "ownership" | "support" | "direct";
className?: string;

dtsPropsFor.Breadcrumbs:
/** Trail, home first; the last item is the current page and has no href. */
items: { label: string; href?: string }[];
/** Accessible name for the nav, e.g. "Breadcrumb". */
label: string;

dtsPropsFor.CtaBand:
/** Heading, one-line body and the button label; waMessage is the pre-filled WhatsApp text the site builds waHref from. */
cta: { title: string; body: string; label: string; waMessage: string };
/** The button's href (a wa.me link on the site). */
waHref: string;

dtsPropsFor.OnThisPage:
/** The page's sections, in order; each becomes a jump link to #id. */
sections: { id: string; title: string }[];
/** Accessible name / visible label, e.g. "On this page". */
label: string;
